import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

square_matrix_multiplication_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Tiled matrix multiplication with shared memory and coalesced access
__global__ void square_matrix_multiplication_kernel(const float* A, const float* B, float* C, int N) {
    // Block size
    const int TILE_DIM = 16;

    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM]; // sB is loaded transposed for coalesced access

    // Thread identifiers
    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    int numTiles = (N + TILE_DIM - 1) / TILE_DIM;
    for (int t = 0; t < numTiles; ++t) {
        // Load tiles into shared memory with coalesced access
        // For sA: row-major access is fine, threadIdx.y for row, threadIdx.x for col
        int aRow = row;
        int aCol = t * TILE_DIM + threadIdx.x;
        if (aRow < N && aCol < N) {
            sA[threadIdx.y][threadIdx.x] = A[aRow * N + aCol];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        // For sB: load transposed for coalesced access during load and then dot product
        // threadIdx.x for sB_row, threadIdx.y for sB_col
        int bRow = t * TILE_DIM + threadIdx.x; // Access B with threadIdx.x for rows
        int bCol = col;                       // and col for columns
        if (bRow < N && bCol < N) {
            sB[threadIdx.x][threadIdx.y] = B[bRow * N + bCol]; // Load B[bRow][bCol] into sB[bCol_thread_idx][bRow_thread_idx]
        } else {
            sB[threadIdx.x][threadIdx.y] = 0.0f; // Pad with zeros if out of bounds
        }
        __syncthreads();

        // Perform dot product on shared memory tiles
        if (row < N && col < N) {
            for (int i = 0; i < TILE_DIM; ++i) {
                sum += sA[threadIdx.y][i] * sB[i][threadIdx.x]; // sB is transposed so sB[i][threadIdx.x] is accessing original B[threadIdx.x][i]
            }
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

